#pragma once

#include <carb/Types.h>
#include <omni/core/IObject.h>
#include <omni/fabric/IdTypes.h>

namespace carb
{
namespace ujitso
{

// Abstract shared stage reader interface for UJITSO build system
class ISharedStageReader : public omni::core::Inherits<omni::core::IObject, OMNI_TYPE_ID("carb.ujitso.ISharedStageReader")>
{
public:
    virtual omni::fabric::FabricId getFabricId() const = 0;
    virtual omni::fabric::StageReaderWriterId getStageReaderId() const = 0;
    virtual omni::fabric::SimStageWithHistoryId getSimStageWithHistoryId() const = 0;
    virtual omni::fabric::UsdStageId getUsdStageId() const = 0;
};

// Interface extension of ISharedStageReader to release all references held by ISharedStageReader so that they are no longer managed by the ISharedStageReader lifetime
class ISharedStageReaderRelease : public omni::core::Inherits<omni::core::IObject, OMNI_TYPE_ID("carb.ujitso.ISharedStageReaderRelease")>
{
public:
    virtual void releaseReferences() = 0;
};

// See SharedStageReaderUtils for helpers

}
}
